events.script:
#uses &quot;classes/navigation/MapNavigator.ctl&quot;
#uses &quot;classes/navigation/NavigationScope.ctl&quot;
#uses &quot;classes/Map/MapObject.ctl&quot;

shared_ptr&lt;MapNavigator&gt; mapNavigator = nullptr;
string navigatorScope;

void initialize()
{
  // This panel runs in a module the navigator attached to its scope, so it
  // can find its navigator without being told which one it belongs to.
  navigatorScope = NavigationScope::current();
  mapNavigator = MapNavigator::find(navigatorScope);

  if (mapNavigator == nullptr)
  {
    DebugTN(__FUNCTION__, __LINE__, &quot;No map navigator for scope:&quot;, navigatorScope);
    return;
  }

  mapNavigator.setMapWidget(getShape(myModuleName(), myPanelName(), &quot;mapEWO&quot;));
  mapEWO.workOffline(false);
  addDatapoints();
}

void addDatapoints()
{
  dyn_string dpes = mapNavigator.getDPEnames();

  for (int i = 1; i &lt;= dynlen(dpes); ++i)
  {
    string dp = dpes[i];
    dyn_string views;
    dpGet(dp + &quot;.Internal.views&quot;, views);
    shared_ptr&lt;MapObject&gt; mapObject = mapNavigator.getMapObject(dpes[i]);

    if (mapObject == nullptr)
      continue;

    for(int j=1; j&lt;=dynlen(views); j++)
    {
      string prefix = &quot;min&quot;;
      dyn_string viewContent = strsplit(views[j], &quot;,&quot;);
      string panel = viewContent[1];
      string options = viewContent[2];
      string methods;
      if(dynlen(viewContent) &gt; 2)
      {
        methods = viewContent[3];
      }
      addSymbol(self, panel, &quot;symb_&quot; + i + &quot;_&quot; + j, makeDynString(&quot;$DP:&quot; + dpes[i],
                                                                  &quot;$Number:1&quot;,
                                                                  &quot;$cnsPath:&quot; + mapObject.getCnsPath(),
                                                                  &quot;$NavigatorName:&quot; + navigatorScope), 10, 10, 0, 1, 1, &quot;mapEWO&quot;);

      if(methods != &quot;&quot;)
      {
        shape s = getShape(myModuleName(), myPanelName(), &quot;symb_&quot; + i + &quot;_&quot; + j);
        dyn_string methodsContent = strsplit(methods, &quot;|&quot;);
        mapping m;
        for(int k=1; k&lt;=dynlen(methodsContent); k++)
        {
          dyn_string method = strsplit(methodsContent[k], &quot;:&quot;);
          DebugTN(__FUNCTION__, __LINE__, &quot;Invoking method: &quot; + method[1] + &quot; &quot;, method[2]);
          invokeMethod(s, method[1], (int)method[2]);
        }
      }

      dyn_string optionsContent = strsplit(options, &quot;|&quot;);
      mapping m;
      for(int k=1; k&lt;=dynlen(optionsContent); k++)
      {
        dyn_string option = strsplit(optionsContent[k], &quot;:&quot;);
        m[option[1]] = option[2];
      }

      mapEWO.addSymbol(&quot;symb_&quot; + i + &quot;_&quot; + j, mapObject.getCoordinates(), m);
    }
  }

  mapNavigator.setReady(true);
  DebugTN(__FILE__, __FUNCTION__, __LINE__);
}

